  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C27"],
      "claim": "Testosterone undecanoate, a lipophilic long-chain ester prodrug, showed absolute oral bioavailability of 6.83 ± 3.32% in young women, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C53"],
      "claim": "Oral testosterone (as a single dose) had an absolute bioavailability of 3.66 ± 2.45%, indicating low systemic availability for a lipophilic steroid ester prodrug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C58"],
      "claim": "Dimethandrolone undecanoate, another long-chain ester prodrug, showed poor and inconsistent oral bioavailability in men, supporting low F for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C55"],
      "claim": "Delmopinol, a lipophilic heterocycle with a long alkyl chain, had very low oral bioavailability after swallowing, consistent with low systemic exposure for such lipophilic molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Tetrabenazine had very low oral systemic availability (mean 0.049 ± 0.032), but its structural dissimilarity limits transferability; still directionally supportive of low F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a lipophilic ester/amide with a long alkyl chain, most analogous to long-chain ester prodrugs such as testosterone undecanoate and dimethandrolone undecanoate, which consistently show low absolute oral bioavailability (3.7–6.8% or poor). Other structurally dissimilar low-F drugs provide weaker supportive evidence. No affirmative evidence suggests F ≥ 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "No data on the specific metabolic stability of the tetrahydrofuranone ester or formamide moieties.",
    "Uncertainty about whether lymphatic absorption could raise F above 20% for this particular long-chain ester/amide."
  ],
